#!/usr/bin/env node
/**
 * Writes docs/DEFECTS.md: one row per pull request that went red on TestSprite, then green, from
 * src/data/loop-iterations.json (GitHub API: every commit's "TestSprite V3" status and the execution
 * it links) and testsprite_tests/red-runs.json (why each red run happened). Do not edit the output.
 *
 *   node scripts/defects-ledger.mjs
 */
import { readFileSync, writeFileSync } from "node:fs";

const REPO = "https://github.com/mohamedwael201193/ninety";
const loop = JSON.parse(readFileSync("src/data/loop-iterations.json", "utf8"));
const why = JSON.parse(readFileSync("testsprite_tests/red-runs.json", "utf8"));
const KIND = { app: "App defect", ux: "UX", "plan-ci": "Test plan / CI" };

// The 7 real app bugs, one line each (README "What TestSprite caught"; #41 caught two).
export const BUGS = [
  { pr: 8, bug: "The parity table's row loop started at index 1 and dropped the first scenario" },
  { pr: 14, bug: "The planner ignored the days of an open stay before a planned trip" },
  { pr: 39, bug: "A demo scenario was lost on the way to /ees and /letter" },
  { pr: 41, bug: "Reloading a ?fresh=1 page wiped saved trips again" },
  { pr: 41, bug: "The letter's evidence table difference cell read as blank" },
  { pr: 55, bug: "Closing the trip sheet with Escape left keyboard focus on the page body instead of \"Add trip\"" },
  { pr: 57, bug: "/parity said \"couldn't verify\" because the live Commission page did not come back as the calculator from Vercel's servers (TS02, also red on production); fixed by using the stored, hash-checked copy" },
];

const short = (sha) => sha.slice(0, 7);
const commit = (sha) => `[\`${short(sha)}\`](${REPO}/commit/${sha})`;
const API = "https://api.github.com/repos/mohamedwael201193/ninety/commits";
const run = (id, sha) => ` ([status JSON](${API}/${sha}/statuses)${id ? `, execution \`${id.slice(0, 8)}\`` : ""})`;

const rows = loop.iterations.filter((it) => it.redThenGreen).map((it) => {
  const reds = it.checks.filter((c) => c.state === "failure" && /\d+\/\d+ passed/.test(c.description));
  const lastRed = it.checks.lastIndexOf(reds.at(-1));
  const green = it.checks.slice(lastRed + 1).find((c) => c.state === "success");
  return { it, reds, green };
});

const appRows = rows.filter((r) => r.it.kind === "app").length;
if (rows.length !== 14 || BUGS.length !== 7 || appRows !== new Set(BUGS.map((b) => b.pr)).size) {
  throw new Error(`ledger out of step: ${rows.length} rows, ${appRows} app rows, ${BUGS.length} bugs`);
}

const out = [
  "# Defect ledger: every red-then-green pull request",
  "",
  "Generated by [`scripts/defects-ledger.mjs`](../scripts/defects-ledger.mjs) from [`src/data/loop-iterations.json`](../src/data/loop-iterations.json) (GitHub API: each commit's `TestSprite V3` status and the TestSprite execution it links, see [LOOP-ITERATIONS.md](../LOOP-ITERATIONS.md)) and [`testsprite_tests/red-runs.json`](../testsprite_tests/red-runs.json). Do not edit by hand. Each \"status JSON\" link is the public GitHub API record of what `testsprite[bot]` posted on that commit; the execution id names the TestSprite run behind it.",
  "",
  `**${rows.length} pull requests went red on TestSprite, then green** (of ${loop.iterations.length} merged through #${loop.iterations.at(-1).pr}): ${rows.filter((r) => r.it.kind === "app").length} with app defects (**${BUGS.length} real bugs**), ${rows.filter((r) => r.it.kind === "ux").length} UX loading state, ${rows.filter((r) => r.it.kind === "plan-ci").length} where the test plan or CI was wrong. Red evidence is every failing \`TestSprite V3\` status on the PR; green is the first passing status after the last red one. Runs that could not start or were blocked before any test ran (#9, #44) are not counted.`,
  "",
  "## The 7 real app bugs",
  "",
  "| # | PR | Bug |",
  "|---|---|---|",
  ...BUGS.map((b, i) => `| ${i + 1} | [#${b.pr}](${REPO}/pull/${b.pr}) | ${b.bug} |`),
  "",
  "The 8 bugs on #57 found by code review (TS45–TS52 pushed red on purpose, `34/43 passed · 8 failed · 1 blocked`, then `All 43 tests passed`) are real too, but TestSprite did not find them first, so they are not in the 7.",
  "",
  "## Ledger",
  "",
  "| PR | Category | Red (TestSprite V3) | Green (first pass after the last red) | Merged | Why it was red |",
  "|---|---|---|---|---|---|",
  ...rows.map(({ it, reds, green }) => [
    `[#${it.pr}](${REPO}/pull/${it.pr}) ${it.title.replace(/\|/g, "/")}`,
    KIND[it.kind] ?? it.kind,
    reds.map((c) => `\`${c.description}\` on ${commit(c.sha)}${run(c.execution, c.sha)}`).join("<br>"),
    green ? `\`${green.description}\` on ${commit(green.sha)}${run(green.execution, green.sha)}` : "none",
    commit(it.mergeCommit),
    String(why[String(it.pr)]?.why ?? "").replace(/\|/g, "/"),
  ].join(" | ")).map((line) => `| ${line} |`),
  "",
];
writeFileSync("docs/DEFECTS.md", out.join("\n"));
console.log(`docs/DEFECTS.md: ${rows.length} rows, ${BUGS.length} bugs`);
